list_pages.code:
var response = await client.Pages.ListPagesAsync(
    new Dictionary<string, object?> { ["search"] = "about", ["visibility"] = "open", ["sort"] = "name", ["order"] = "asc" });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var page in ((IReadOnlyList<object?>)body["pages"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{page["id"]} {page["name"]} {page["url"]} {page["visibility"]} {page["landing"]}");
var pagination = (IReadOnlyDictionary<string, object?>)body["pagination"]!;
Console.WriteLine($"{pagination["total"]} {pagination["has_next"]}");

